import { getHostEnvExcludingEnvFile } from "../../platform/compat/process.js";
import { parseConfiguredPlatformRoots } from "../../server/utils/domain-parser.js";
import { parseOperatorStudioOrigin } from "./studio-origin-policy.js";
// Ignore values copied from the project `.env`; this setting belongs to the operator.
const OPERATOR_STUDIO_ORIGIN = parseOperatorStudioOrigin(getHostEnvExcludingEnvFile("PLATFORM_STUDIO_ORIGIN"), parseConfiguredPlatformRoots(getHostEnvExcludingEnvFile("PLATFORM_DOMAIN_SUFFIXES")));
/** The operator's exact Studio origin, outside project-scoped environment views. */
export function getOperatorStudioOrigin() {
    return OPERATOR_STUDIO_ORIGIN;
}
